import type {
  BenchPlan,
  ComponentName,
  ImplementationName,
  ScenarioAction,
  ScenarioName,
} from './types';

const ACTIONS: readonly ScenarioAction[] = [
  'mount',
  'update',
  'memory',
  'leak',
];

/**
 * Components other than the first one carry their name in the scenario cell.
 * `switch` is deliberately absent: its cells are the bare action names, which
 * is what every pre-G1 results file and baseline says.
 */
const SUFFIXED_COMPONENTS: readonly Exclude<ComponentName, 'switch'>[] = [
  // @generated by scripts/gen-registry.mjs (region: suffixed-components) - do not edit; run bun run regen
  'slider',
  'button',
  'progress',
  'segmented-control',
  'date-picker',
  'picker',
  // @end-generated
];

const IMPLEMENTATIONS: readonly ImplementationName[] = [
  'rn-core',
  'expo-ui-host-per-control',
  'expo-ui-shared-host',
  'nitro-ui',
  // The library's own controls in one shared composition (`Host`). It is a
  // cell the arm itself refuses for any component but Switch
  // (`BenchImplementation.components`), which is why it can sit in the shared plan.
  'nitro-ui-host',
];

/**
 * Split `update.slider` into its action and component. A bare action is the
 * first component's cell. Returns null for anything else, including a
 * `mount.button` - a cell the plan asks for that no arm implements must fail
 * the launch, not measure the wrong control.
 */
function splitScenario(value: string): [ScenarioAction, ComponentName] | null {
  const dot = value.indexOf('.');
  if (dot === -1) {
    return (ACTIONS as readonly string[]).includes(value)
      ? [value as ScenarioAction, 'switch']
      : null;
  }
  const action = value.slice(0, dot);
  const component = value.slice(dot + 1);
  if (
    !(ACTIONS as readonly string[]).includes(action) ||
    !(SUFFIXED_COMPONENTS as readonly string[]).includes(
      component as Exclude<ComponentName, 'switch'>
    )
  ) {
    return null;
  }
  return [action as ScenarioAction, component as ComponentName];
}

function isImplementation(value: string): value is ImplementationName {
  return (IMPLEMENTATIONS as readonly string[]).includes(value);
}

/**
 * Cells whose arm cannot produce a mounting transaction, so the probe's mount
 * hook has nothing to stamp: `update.slider:rn-core` flips a value the floor
 * `View` does not take (`implementations/rnCore.tsx`), which means the commit
 * changes no props on any native node, so no transaction is created and both
 * signals time out - 1.5 s + 2 s per iteration, about 95 s per launch, for two
 * numbers that are `n/a` in the table either way.
 *
 * Keyed `scenario:implementation`, because it is a property of the pair: the
 * same arm *does* signal on `mount.slider` (mounting 50 views is a transaction)
 * and `rn-core` signals on every `switch` cell.
 */
const NO_MOUNT_SIGNAL: readonly string[] = [
  'update.slider:rn-core',
  // The same shape for Progress: RN core's control arm is an `ActivityIndicator`
  // (G3 brief), which has no value to flip, so a `update.progress` commit
  // changes no native prop and creates no transaction.
  'update.progress:rn-core',
];

/**
 * The launch-flag names the parser accepts, and the defaults they override.
 *
 * All four live here, and `probe.ts` imports the defaults from here, because this
 * file must stay free of the probe: `probe.ts` creates the native hybrid object at
 * import time, and a plan string has to parse - and reject a bad flag loudly - before
 * anything touches Nitro.
 */
export const MOUNT_TIMEOUT_FLAG = 'mountTimeout';
export const PRESENTED_TIMEOUT_FLAG = 'presentedTimeout';

/**
 * How long the runner waits for each native signal before calling it missing.
 *
 * A4: both are overridable from the launch plan (`scenario:impl:N:presentedTimeout=40000`)
 * because "is the sample missing because it never happened, or because we stopped
 * asking?" can only be answered by asking for longer. A run that raises one is stamped
 * `presentedTimeoutMs` in its results file and is diagnostic, not baseline material: a
 * sample that arrives keeps its value, but *which* samples arrive moves the median.
 *
 * Not the whole story on either platform: the native side also refuses to wait forever
 * for a presenting frame (iOS: the safety timer in `BenchProbeArmPresentation`;
 * Android: `FRAME_TIMEOUT_MS`), so a wait above that ceiling is still answered `-1` by
 * the ceiling. Both are documented next to their `dispatch_after`/`postDelayed`.
 */
export const DEFAULT_MOUNT_TIMEOUT_MS = 1500;
/**
 * How long a launch waits for the presenting frame.
 *
 * 8 000 ms, raised from 2 000 by A4 on measured data (`docs/tasks/
 * A4-ios-baseline-mac2.report.md`): on the canonical iPhone 17 simulator, 200 `@expo/ui`
 * DatePickers present their first frame at p50 ~2.7-3.0 s - *above* the old 2 s - so only
 * 56 of 160 and 69 of 160 measured iterations produced a presenting sample, and two
 * reference cells were unusable. The worst frame seen anywhere in A4's runs was 3.9 s, so
 * 8 s leaves roughly a doubling of the slowest measurement before samples drop again.
 *
 * The change is value-neutral for any cell that is already complete: every iteration that
 * answered within 2 s answers with the identical stamp under 8 s, so the median cannot
 * move. It changes only cells that were losing samples - which is the point, and why the
 * committed baselines (every cell of which is complete by the mint rule) stay comparable.
 */
export const DEFAULT_PRESENTED_TIMEOUT_MS = 8000;

/**
 * The largest timeout a launch plan may ask for.
 *
 * It must stay below both platforms' native backstops (90 s: iOS
 * `kBenchPresentationCeilingSeconds`, Android `PRESENTATION_CEILING_MS`) so the
 * requested wait is always the one that answers, and the ceiling is always the thing
 * that catches a process that cannot draw at all. A wall-clock `mount` launch is 25
 * iterations x (mount + presented) plus pacing, so a caller that asks near the cap
 * also raises the runner's per-launch budget (`BENCH_LAUNCH_TIMEOUT_S`) - which is
 * exactly what the A4 time-to-present diagnostic run does.
 */
export const MAX_TIMEOUT_MS = 80_000;

/**
 * Parse the `scenario:implementation:N[:flags]` launch argument, where `flags` is a
 * comma-separated list of:
 *
 * - `marks` - ask the runtime for its own native perf marks (`bun bench --perf-marks`);
 * - `presentedTimeout=<ms>` - how long to wait for the presenting frame;
 * - `mountTimeout=<ms>` - how long to wait for the mount signal.
 *
 * They are part of the launch argument rather than an env var because a release build
 * has no env, and one launch must be fully described by the string the runner passed
 * it. The timeouts are here at all because "this arm never draws" and "this arm draws
 * slower than we wait" are the same null in the results file otherwise (A4).
 *
 * Returns null for an unconfigured launch, which renders the idle screen.
 */
export function parsePlan(raw: string): BenchPlan | null {
  if (raw.length === 0) {
    return null;
  }
  const parts = raw.split(':');
  const [scenario, implementation, count, flags] = parts;
  const halves = scenario == null ? null : splitScenario(scenario);
  if (
    (parts.length !== 3 && parts.length !== 4) ||
    scenario == null ||
    implementation == null ||
    count == null ||
    halves === null ||
    !isImplementation(implementation)
  ) {
    throw new Error(
      `NITRO_BENCH unparseable plan "${raw}" (expected scenario:implementation:N, ` +
        `got scenarios ${ACTIONS.map((action) =>
          [action, ...SUFFIXED_COMPONENTS.map((c) => `${action}.${c}`)].join(
            '|'
          )
        ).join('|')} and implementations ${IMPLEMENTATIONS.join('|')})`
    );
  }
  const n = Number(count);
  if (!Number.isInteger(n) || n < 0) {
    throw new Error(
      `NITRO_BENCH plan "${raw}" has a non-negative integer count`
    );
  }
  let perfMarks = false;
  let mountTimeoutMs = DEFAULT_MOUNT_TIMEOUT_MS;
  let presentedTimeoutMs = DEFAULT_PRESENTED_TIMEOUT_MS;
  for (const flag of (flags ?? '').split(',').map((part) => part.trim())) {
    if (flag === '') {
      continue;
    }
    if (flag === 'marks') {
      perfMarks = true;
      continue;
    }
    const [name, value, extra] = flag.split('=');
    const ms = Number(value);
    if (
      extra != null ||
      value == null ||
      value === '' ||
      !Number.isFinite(ms) ||
      ms < 1 ||
      ms > MAX_TIMEOUT_MS
    ) {
      throw new Error(
        `NITRO_BENCH plan "${raw}" has an unknown or malformed flag "${flag}" ` +
          `(known: marks, ${MOUNT_TIMEOUT_FLAG}=<1..${String(MAX_TIMEOUT_MS)}>, ` +
          `${PRESENTED_TIMEOUT_FLAG}=<1..${String(MAX_TIMEOUT_MS)}>)`
      );
    }
    if (name === MOUNT_TIMEOUT_FLAG) {
      mountTimeoutMs = ms;
    } else if (name === PRESENTED_TIMEOUT_FLAG) {
      presentedTimeoutMs = ms;
    } else {
      throw new Error(
        `NITRO_BENCH plan "${raw}" has an unknown flag "${name}" ` +
          `(known: marks, ${MOUNT_TIMEOUT_FLAG}, ${PRESENTED_TIMEOUT_FLAG})`
      );
    }
  }
  const [action, component] = halves;
  return {
    scenario: scenario as ScenarioName,
    action,
    component,
    implementation,
    n,
    mountSignal: !NO_MOUNT_SIGNAL.includes(`${scenario}:${implementation}`),
    perfMarks,
    mountTimeoutMs,
    presentedTimeoutMs,
  };
}
